def congelar_porcentajes(apps, schema_editor):
    """Las ventas ya registradas guardan el % base que la trabajadora tiene hoy: así, si después se
    cambia su comisión, el pasado no se recalcula."""
    DetalleVenta = apps.get_model("ventas", "DetalleVenta")
    lineas = DetalleVenta.objects.filter(trabajador__isnull=False, porcentaje_comision__isnull=True)
    for linea in lineas.select_related("trabajador").iterator():
        linea.porcentaje_comision = linea.trabajador.porcentaje_comision or 0
        linea.save(update_fields=["porcentaje_comision"])


